<?php
declare(strict_types=1);
require dirname(__DIR__).'/config/bootstrap.php';
require __DIR__.'/_common.php';
permohonan_ensure($pdo);$error='';
if(isset($_GET['keluar'])){unset($_SESSION['pemohon']);redirect('permohonan/index.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='daftar'){
   $name=trim((string)$_POST['nama_lengkap']);$username=trim((string)$_POST['username']);$email=trim((string)$_POST['email']);$password=(string)$_POST['password'];
   if($name===''||$username===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)throw new RuntimeException('Lengkapi data. Password minimal 8 karakter.');
   $pdo->prepare('INSERT INTO akun_pemohon(nama_lengkap,username,email,whatsapp,password) VALUES(?,?,?,?,?)')->execute([$name,$username,$email,trim((string)($_POST['whatsapp']??'')),password_hash($password,PASSWORD_DEFAULT)]);
   $_SESSION['pemohon']=['id'=>(int)$pdo->lastInsertId(),'nama_lengkap'=>$name,'email'=>$email];flash('success','Akun berhasil dibuat. Silakan isi permohonan.');redirect('permohonan/index.php');
  }
  if($action==='masuk'){
   $identity=trim((string)$_POST['identity']);$q=$pdo->prepare("SELECT * FROM akun_pemohon WHERE (username=? OR email=?) AND status='aktif'");$q->execute([$identity,$identity]);$account=$q->fetch();
   if(!$account||!password_verify((string)$_POST['password'],$account['password']))throw new RuntimeException('Username/email atau password salah.');
   $_SESSION['pemohon']=['id'=>(int)$account['id'],'nama_lengkap'=>$account['nama_lengkap'],'email'=>$account['email']];redirect('permohonan/index.php');
  }
  if($action==='ajukan'){
   if(!pemohon_logged_in())throw new RuntimeException('Silakan masuk terlebih dahulu.');
   $client=trim((string)$_POST['nama_klien']);$project=trim((string)$_POST['nama_proyek']);if($client===''||$project==='')throw new RuntimeException('Nama klien dan proyek wajib diisi.');
   $pdo->prepare('INSERT INTO permohonan(nomor_permohonan,pemohon_id,nama_klien,nama_perusahaan,nama_kontak,whatsapp,email,alamat_klien,kabupaten_klien,provinsi_klien,npwp,nama_proyek,nama_pekerjaan,pemilik_pekerjaan,alamat_lokasi,desa,kecamatan,kabupaten,provinsi,jumlah_titik_rencana,tanggal_rencana,catatan_pemohon) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
    ->execute([permohonan_number($pdo),(int)$_SESSION['pemohon']['id'],$client,trim((string)($_POST['nama_perusahaan']??'')),trim((string)($_POST['nama_kontak']??'')),trim((string)($_POST['whatsapp']??'')),trim((string)($_POST['email']??'')),trim((string)($_POST['alamat_klien']??'')),trim((string)($_POST['kabupaten_klien']??'')),trim((string)($_POST['provinsi_klien']??'')),trim((string)($_POST['npwp']??'')),$project,trim((string)($_POST['nama_pekerjaan']??'')),trim((string)($_POST['pemilik_pekerjaan']??'')),trim((string)($_POST['alamat_lokasi']??'')),trim((string)($_POST['desa']??'')),trim((string)($_POST['kecamatan']??'')),trim((string)($_POST['kabupaten']??'')),trim((string)($_POST['provinsi']??'')),max(1,(int)($_POST['jumlah_titik_rencana']??1)),$_POST['tanggal_rencana']?:null,trim((string)($_POST['catatan_pemohon']??''))]);
   flash('success','Permohonan berhasil dikirim dan menunggu pemeriksaan laboratorium.');redirect('permohonan/index.php');
  }
 }catch(PDOException $e){$error=$e->getCode()==='23000'?'Username atau email sudah digunakan.':'Data tidak dapat disimpan.';}catch(Throwable $e){$error=$e->getMessage();}
}
$requests=[];if(pemohon_logged_in()){$q=$pdo->prepare('SELECT * FROM permohonan WHERE pemohon_id=? ORDER BY id DESC');$q->execute([(int)$_SESSION['pemohon']['id']]);$requests=$q->fetchAll();}
