<?php if(!pemohon_logged_in()):?><div class="row g-4"><div class="col-lg-7"><div class="card"><div class="card-body p-4"><h3><span class="step">1</span> Buat akun pemohon</h3><form method="post" class="row g-3 mt-1"><?=csrf_field()?><input type="hidden" name="action" value="daftar"><div class="col-md-6"><label class="form-label required">Nama lengkap</label><input class="form-control" required name="nama_lengkap"></div><div class="col-md-6"><label class="form-label required">Username</label><input class="form-control" required name="username"></div><div class="col-md-6"><label class="form-label required">Email</label><input class="form-control" type="email" required name="email"></div><div class="col-md-6"><label class="form-label">WhatsApp</label><input class="form-control" name="whatsapp"></div><div class="col-md-6"><label class="form-label required">Password</label><input class="form-control" type="password" minlength="8" required name="password"></div><div class="col-12"><button class="btn btn-primary px-4">Buat akun & lanjutkan</button></div></form></div></div></div>
<div class="col-lg-5"><div class="card"><div class="card-body p-4"><h3>Sudah punya akun?</h3><form method="post" class="mt-3"><?=csrf_field()?><input type="hidden" name="action" value="masuk"><div class="mb-3"><label class="form-label">Username atau email</label><input class="form-control" required name="identity"></div><div class="mb-3"><label class="form-label">Password</label><input class="form-control" type="password" required name="password"></div><button class="btn btn-outline-primary w-100">Masuk</button></form></div></div></div></div>
<?php else:?><div class="row g-4"><div class="col-xl-8"><div class="card"><div class="card-body p-4"><h3><span class="step">2</span> Isi data permohonan</h3><form method="post" class="mt-3"><?=csrf_field()?><input type="hidden" name="action" value="ajukan">
<h5 class="border-bottom pb-2 mt-3">Data Klien</h5><div class="row g-3"><div class="col-md-6"><label class="form-label required">Nama klien</label><input class="form-control" required name="nama_klien"></div><div class="col-md-6"><label class="form-label">Perusahaan/instansi</label><input class="form-control" name="nama_perusahaan"></div><div class="col-md-6"><label class="form-label">Nama kontak</label><input class="form-control" name="nama_kontak" value="<?=e($_SESSION['pemohon']['nama_lengkap'])?>"></div><div class="col-md-3"><label class="form-label">WhatsApp</label><input class="form-control" name="whatsapp"></div><div class="col-md-3"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?=e($_SESSION['pemohon']['email'])?>"></div><div class="col-12"><label class="form-label">Alamat klien</label><textarea class="form-control" name="alamat_klien"></textarea></div><div class="col-md-4"><label class="form-label">Kabupaten/Kota</label><input class="form-control" name="kabupaten_klien"></div><div class="col-md-4"><label class="form-label">Provinsi</label><input class="form-control" name="provinsi_klien"></div><div class="col-md-4"><label class="form-label">NPWP</label><input class="form-control" name="npwp"></div></div>
<h5 class="border-bottom pb-2 mt-4">Data Proyek</h5><div class="row g-3"><div class="col-md-7"><label class="form-label required">Nama proyek</label><input class="form-control" required name="nama_proyek"></div><div class="col-md-5"><label class="form-label">Nama pekerjaan</label><input class="form-control" name="nama_pekerjaan" value="Pengujian Sondir"></div><div class="col-md-6"><label class="form-label">Pemilik pekerjaan</label><input class="form-control" name="pemilik_pekerjaan"></div><div class="col-md-3"><label class="form-label">Jumlah titik</label><input class="form-control" type="number" min="1" name="jumlah_titik_rencana" value="1"></div><div class="col-md-3"><label class="form-label">Tanggal rencana</label><input class="form-control" type="date" name="tanggal_rencana"></div><div class="col-12"><label class="form-label required">Alamat lokasi proyek</label><textarea class="form-control" required name="alamat_lokasi"></textarea></div><div class="col-md-3"><label class="form-label">Desa/Kelurahan</label><input class="form-control" name="desa"></div><div class="col-md-3"><label class="form-label">Kecamatan</label><input class="form-control" name="kecamatan"></div><div class="col-md-3"><label class="form-label">Kabupaten/Kota</label><input class="form-control" name="kabupaten"></div><div class="col-md-3"><label class="form-label">Provinsi</label><input class="form-control" name="provinsi"></div><div class="col-12"><label class="form-label">Catatan</label><textarea class="form-control" name="catatan_pemohon"></textarea></div><div class="col-12"><button class="btn btn-primary btn-lg"><i class="bi bi-send me-1"></i>Ajukan permohonan</button></div></div></form></div></div></div>
